import sys
from collections import defaultdict
import itertools

# Load and clean dictionary
with open("/workdir/data/dict.txt") as f:
    raw_words = [line.strip() for line in f]

valid_words = set()
valid_words_list = []
for w in raw_words:
    if len(w) >= 4 and w.isalpha():
        wl = w.lower()
        if wl not in valid_words:
            valid_words.add(wl)
            valid_words_list.append(wl)

print(f"Total valid words (len>=4, alpha only): {len(valid_words)}")

# For each word, find all other words that can be reached by a consistent letter substitution
# where no letter maps to itself

def can_map(w1, w2, existing_map=None):
    """Check if w1 can be mapped to w2 with a consistent bijection where no letter maps to itself.
    existing_map is a partial mapping dict."""
    if len(w1) != len(w2):
        return None

    mapping = dict(existing_map) if existing_map else {}
    reverse = {}
    for k, v in mapping.items():
        reverse[v] = k

    for c1, c2 in zip(w1, w2):
        if c1 == c2:
            return None  # derangement requires no fixed points
        if c1 in mapping:
            if mapping[c1] != c2:
                return None
        else:
            if c2 in reverse:
                return None
            mapping[c1] = c2
            reverse[c2] = c1

    return mapping

# Strategy: find word pairs and try to build a consistent mapping
# Let's try a greedy approach

# Group words by length
by_length = defaultdict(list)
for w in valid_words:
    by_length[len(w)].append(w)

print("Words by length:")
for l in sorted(by_length.keys()):
    print(f"  len {l}: {len(by_length[l])} words")

# Find compatible word pairs
pairs_by_len = {}
for length, words in by_length.items():
    if length < 4 or length > 8:
        continue
    pairs = []
    word_set = set(words)
    for w1 in words:
        for w2 in words:
            if w1 == w2:
                continue
            m = can_map(w1, w2)
            if m is not None:
                pairs.append((w1, w2, m))
    pairs_by_len[length] = pairs
    print(f"  Length {length}: {len(pairs)} pairs")

